-- Import secrétariat 2025
-- Source : Desktop/ngor almadies/YATAL/2025/Yataal MBAYANG2.xlsx
--   Feuilles TRI 1, TRI 2, TRI 3, TRI4.
-- S'ajoute aux imports 2023 et 2024. Les NICAD déjà écrits dans ces fichiers sont exclus.
--
-- Mêmes tables que le formulaire secrétariat :
--   dossiers, references_cadastrales, titulaires, terrains.
--   Pas d'attribution. txt_agentTraiteur reste vide.
--   Date d'état absente du classeur : 2025-12-31.
--
-- NICAD = code commune + section (3) + parcelle (5) + appartement (3).
--   Ngor 01130132, Ouakam 01130131, Yoff 01130133.
--   15 ou 18 chiffres commençant par 1130 : le zéro manquant est ajouté.
--   La date et le lieu de naissance sont séparés.
--
-- Doublon strict : même txt_num_titre, ou même titre mère avec le même lot.
--   Trim, majuscules, espaces autour du /. 15/S reste différent de S 15.
--   000 et 0 ne sont pas un lot. Un lot seul, ou un titre mère seul, n'est pas un doublon.
--   Deux NICAD différents pour le même triple sont conservés.
--   Un NICAD déjà présent en 2023 ou 2024 n'est pas réimporté.
--
-- Lignes lues : 2155
-- Lignes retenues : 716
-- Déjà en base (NICAD) : 1397
-- Déjà en base (même triple, sans NICAD nouveau) : 4
-- Même triple qu'en base, NICAD nouveau, conservées : 4
-- Ignorées : commune inconnue 0, vides 0
-- Doublons de triple écartés : 13
-- Même triple mais NICAD différent, conservées : 10
-- Doublons de NICAD écartés : 25
-- NICAD découpés : 685
-- Appartements : 0
-- Dates de naissance séparées : 604
-- Lieux de naissance : 570
-- Commune du fichier différente du préfixe : 7
-- Parcelle du fichier différente du NICAD : 9
-- NICAD illisible : 31
-- Par feuille retenue : TRI4 Feuil1 321, TRI 3 Feuil1 289, TRI 2 Feuil1 106
-- Détail : rapport_import_secretariat_2025.txt
-- Identifiants à partir de 12697. Dossiers 00001/2025 et suivants.
-- N° d'ordre à partir de 12695.

SET NAMES utf8mb4;
START TRANSACTION;









































































COMMIT;

-- Contrôle : NICAD = code commune + section + parcelle + appartement.
SELECT COUNT(*) AS nicad_incoherents FROM terrains t
JOIN communes c ON c.id = t.slt_commune
WHERE t.txt_nicad IS NOT NULL AND REPLACE(t.txt_nicad, ' ', '') <> CONCAT(
  REPLACE(c.txt_codeCommune, ' ', ''), IFNULL(t.txt_num_section, ''),
  IFNULL(t.txt_num_parcelle, ''), IFNULL(t.txt_appartement, ''));
